import { Head } from 'vite-react-ssg'
import { COMPANY_NAME, FOUNDER, SITE_URL } from '../content/company'

interface SeoProps {
  title: string
  description: string
  path: string
  /** Extra JSON-LD objects for this page, emitted alongside the sitewide Organization. */
  jsonLd?: object[]
  noindex?: boolean
}

const DEFAULT_OG_IMAGE = `${SITE_URL}/og/home.png`

/** Per-page social image, generated by `npm run og` (scripts/og-images.mjs uses the same names). */
function ogImageFor(path: string, noindex: boolean) {
  if (noindex || path === '/') return DEFAULT_OG_IMAGE
  return `${SITE_URL}/og/${path.slice(1).replace(/\//g, '-')}.png`
}

const ORGANIZATION = {
  '@context': 'https://schema.org',
  '@type': 'ProfessionalService',
  name: COMPANY_NAME,
  url: SITE_URL,
  logo: `${SITE_URL}/icon-512.png`,
  image: DEFAULT_OG_IMAGE,
  description:
    'Founder-led offshore software development studio in India building web, SaaS, data, and AI products for startups and growing businesses.',
  areaServed: 'Worldwide',
  address: { '@type': 'PostalAddress', addressCountry: 'IN' },
  knowsAbout: ['Web development', 'SaaS', 'AI integration', 'Data engineering', 'Test automation'],
  founder: {
    '@type': 'Person',
    name: FOUNDER.name,
    jobTitle: FOUNDER.title,
    image: `${SITE_URL}${FOUNDER.photo}`,
    sameAs: [FOUNDER.linkedin],
  },
}

function Seo({ title, description, path, jsonLd = [], noindex = false }: SeoProps) {
  const fullTitle = path === '/' ? title : `${title} — ${COMPANY_NAME}`
  const url = `${SITE_URL}${path}`
  const image = ogImageFor(path, noindex)

  return (
    <Head>
      <title>{fullTitle}</title>
      <meta name="description" content={description} />
      <link rel="canonical" href={url} />
      {noindex && <meta name="robots" content="noindex" />}

      <meta property="og:type" content="website" />
      <meta property="og:url" content={url} />
      <meta property="og:title" content={fullTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={image} />
      <meta property="og:image:width" content="1200" />
      <meta property="og:image:height" content="630" />
      <meta property="og:site_name" content={COMPANY_NAME} />

      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={fullTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={image} />

      {[ORGANIZATION, ...jsonLd].map((data, index) => (
        <script key={index} type="application/ld+json">
          {JSON.stringify(data)}
        </script>
      ))}
    </Head>
  )
}

export default Seo
